package com.oyuki.marketsquare.entity; import com.oyuki.user.entity.User; import jakarta.persistence.*; import lombok.*; @Entity @Table(name="market_sellers") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class MarketSeller { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(optional=false) @JoinColumn(name="seller_id",unique=true) private User seller; @ManyToOne(optional=false) @JoinColumn(name="market_id") private Market market; private String stallNameOrNumber; private String pickupPoint; @Builder.Default private boolean active=true; }